package bottlesong

import (
	"fmt"
	"strings"
)

var bottleNames = map[int]string{
	0: "no", 1: "one", 2: "two", 3: "three", 4: "four",
	5: "five", 6: "six", 7: "seven", 8: "eight", 9: "nine", 10: "ten",
}

func bottleWord(n int) string {
	if n == 1 {
		return "bottle"
	}
	return "bottles"
}

func titleCase(s string) string {
	if s == "" {
		return s
	}
	return strings.ToUpper(s[:1]) + s[1:]
}

func Recite(startBottles, takeDown int) []string {
	var lines []string
	for n := startBottles; n > startBottles-takeDown; n-- {
		if n < startBottles {
			lines = append(lines, "")
		}
		verse := fmt.Sprintf("%s green %s hanging on the wall,", titleCase(bottleNames[n]), bottleWord(n))
		lines = append(lines,
			verse,
			verse,
			"And if one green bottle should accidentally fall,",
			fmt.Sprintf("There'll be %s green %s hanging on the wall.", bottleNames[n-1], bottleWord(n-1)),
		)
	}
	return lines
}
```

